typedef struct {
    uint16_t vendor_id;
    uint16_t codec_id;     /* 1=H264, 2=HEVC_10B, 3=VP9_P2, 4=AV1_10B */
    uint16_t max_w;
    uint16_t max_h;
    uint16_t max_fps;
    uint8_t  cpu_usage_pct;
    const char *profile_name;
    const char *va_driver;
} vaapi_codec_profile_t;

typedef struct {
    uint16_t vid;
    uint16_t pid;
    uint16_t poll_hz;
    const char *bus_controller;
    const char *device_name;
} usb_nvme_entry_t;

